package app.launcherin.tv;
import android.content.*;import android.app.*;import android.os.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.io.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={34,35})
public class LauncherinMusicVisualTest {
 private Context c;private LauncherinAudioSpectrum.Factory original;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();original=LauncherinAudioSpectrum.factory;}
 @After public void finish(){LauncherinAudioSpectrum.factory=original;}
 @Test public void silenceIsZeroAndKnownFftBinProducesOnlyTheExpectedBandEnergy(){float[] out=new float[48];LauncherinSpectrum.bands(new byte[512],out);for(float v:out)assertEquals(0,v,0);byte[] fft=new byte[512];fft[32]=100;LauncherinSpectrum.bands(fft,out);int positive=0;float max=0;for(float v:out){if(v>0)positive++;max=Math.max(v,max);}assertTrue(positive>0&&positive<8);assertTrue(max>.7f);LauncherinSpectrum.bands(new byte[0],out);for(float v:out)assertEquals(0,v,0);}
 @Test public void defaultStagesUseFiveFifteenThirtyMinutesAndNoFalseRandomMode()throws Exception{LauncherinVisualOptions o=new LauncherinVisualOptions(new JSONObject());assertFalse(o.enabled);assertFalse(o.ambient);assertTrue(o.motion);assertEquals(0,o.stage(299999));assertEquals(1,o.stage(300000));assertEquals(2,o.stage(900000));assertEquals(3,o.stage(1800000));}
 @Test public void legacyGooglePhotosCanRemainSelectedWhileOnlyTheArtworkRingIsEnabled()throws Exception{LauncherinVisualOptions o=new LauncherinVisualOptions(new JSONObject().put("enabled",true).put("smart",false));assertTrue(o.enabled);assertFalse(o.smart);LauncherinVisualOptions.save(c,o);assertFalse(LauncherinVisualOptions.read(c).smart);assertTrue(LauncherinVisualOptions.read(c).enabled);}
 @Test public void invalidOptionsRejectCommandsPathsBadTypesAndOutOfOrderTimes()throws Exception{String[] bad={"{\"command\":\"reboot\"}","{\"intensity\":101}","{\"enabled\":\"true\"}","{\"dim_minutes\":1.5}","{\"hide_minutes\":4}","{\"palette\":\"../../file\"}"};for(String s:bad){try{new LauncherinVisualOptions(new JSONObject(s));fail(s);}catch(JSONException expected){}}}
 @Test public void visualCommitIsScopedToTheActiveProfileAndInvalidCommitKeepsPriorSettings()throws Exception{LauncherinVisualOptions wanted=new LauncherinVisualOptions(new JSONObject().put("enabled",true));LauncherinVisualOptions.save(c,wanted);JSONObject before=LauncherinVisualOptions.read(c).json();writePending(new JSONObject().put("profile","default").put("options",new JSONObject().put("enabled",false)));assertTrue(LauncherinVisualOptions.call(c,"commitMusicVisual").getBoolean("ok"));assertFalse(LauncherinVisualOptions.read(c).enabled);writePending(new JSONObject().put("profile","wrong").put("options",before));assertFalse(LauncherinVisualOptions.call(c,"commitMusicVisual").getBoolean("ok"));assertFalse(LauncherinVisualOptions.read(c).enabled);Bundle status=LauncherinVisualOptions.call(c,"musicVisualStatus");assertEquals(1,status.getInt("schema"));assertEquals("default",new JSONObject(status.getString("json")).getString("profile"));}
 private void writePending(JSONObject value)throws Exception{try(OutputStream out=new FileOutputStream(LauncherinVisualOptions.pending(c))){out.write(value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
 @Test public void visualizationNeverAttachesToGlobalMixAndDoesNotCaptureWithoutPermission(){int[] starts={0};LauncherinAudioSpectrum.factory=()->new FakeCapture(starts);LauncherinAudioSpectrum a=new LauncherinAudioSpectrum();assertFalse(a.sync(c,0,true,false,fft->{}));assertFalse(a.sync(c,-1,true,false,fft->{}));assertFalse(a.sync(c,22,true,false,fft->{}));assertEquals(0,starts[0]);a.close();}
 @Test public void ownSessionCaptureReleasesOnPauseSwitchMinimalAndClose(){Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.RECORD_AUDIO);int[] counts={0,0,0};LauncherinAudioSpectrum.factory=()->new FakeCapture(counts);LauncherinAudioSpectrum a=new LauncherinAudioSpectrum();assertTrue(a.sync(c,41,true,false,fft->{}));assertEquals(1,counts[0]);assertTrue(a.sync(c,41,true,false,fft->{}));assertEquals(1,counts[0]);assertTrue(a.sync(c,41,true,true,fft->{}));assertEquals(5000,counts[2]);assertEquals(1,counts[1]);assertFalse(a.sync(c,41,false,true,fft->{}));assertEquals(2,counts[1]);a.close();assertEquals(2,counts[1]);}
 @Test public void captureFailureIsReportedWithoutFabricatedSpectrum(){Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.RECORD_AUDIO);int[] closed={0};LauncherinAudioSpectrum.factory=()->new LauncherinAudioSpectrum.Capture(){public void start(int id,int rate,LauncherinAudioSpectrum.Listener listener){throw new SecurityException();}public void close(){closed[0]++;}};LauncherinAudioSpectrum a=new LauncherinAudioSpectrum();assertFalse(a.sync(c,8,true,false,fft->fail()));assertTrue(a.status().contains("não disponibilizou"));assertEquals(1,closed[0]);}
 private static class FakeCapture implements LauncherinAudioSpectrum.Capture{final int[] counts;FakeCapture(int[] c){counts=c;}public void start(int id,int rate,LauncherinAudioSpectrum.Listener l){assertTrue(id>0);counts[0]++;if(counts.length>2)counts[2]=rate;l.fft(new byte[512]);}public void close(){if(counts.length>1)counts[1]++;}}
 @Test public void existingDefaultLibraryAndTwoProfilesRemainIsolated()throws Exception{c.getSharedPreferences("launcherin-player",0).edit().putLong("position",12345).commit();LauncherinMusicProfiles profiles=new LauncherinMusicProfiles(c);assertEquals(2,profiles.list().size());assertEquals("launcherin-player",profiles.libraryName());LauncherinMusicLibrary first=new LauncherinMusicLibrary(c);first.write("favorites",Arrays.asList(LauncherinNativeMusicTest.track(0)));first.progress(0,12345);first.saveArtist(new LauncherinMusicLibrary.Artist("Skank","youtube",""));LauncherinVisualOptions.save(c,new LauncherinVisualOptions(new JSONObject().put("enabled",true)));profiles.select(profiles.list().get(1).id);LauncherinMusicLibrary second=new LauncherinMusicLibrary(c);assertTrue(second.read("favorites").isEmpty());assertTrue(second.artists().isEmpty());assertFalse(LauncherinVisualOptions.read(c).enabled);second.progress(0,500);profiles.select("default");assertEquals(12345,new LauncherinMusicLibrary(c).position());assertEquals(1,new LauncherinMusicLibrary(c).read("favorites").size());assertTrue(LauncherinVisualOptions.read(c).enabled);}
 @Test public void playlistsAndRecentAreRealBoundedAndScopedToProfiles(){LauncherinTrack track=LauncherinNativeMusicTest.track(1);LauncherinMusicPlaylists p=new LauncherinMusicPlaylists(c);LauncherinMusicPlaylists.Playlist created=p.create("Minha playlist");p.add(created.id,track);p.add(created.id,track);assertEquals(1,p.read().get(0).tracks.size());LauncherinMusicLibrary l=new LauncherinMusicLibrary(c);for(int i=0;i<35;i++)l.recent(new LauncherinTrack("https://soundcloud.com/fixture/track-"+i,"Faixa "+i,"Artista","",180000,"soundcloud"));assertEquals(30,l.read("recent").size());l.recent(track);assertEquals(track.url,l.read("recent").get(0).url);LauncherinMusicProfiles profiles=new LauncherinMusicProfiles(c);profiles.select(profiles.list().get(1).id);assertTrue(new LauncherinMusicPlaylists(c).read().isEmpty());assertTrue(new LauncherinMusicLibrary(c).read("recent").isEmpty());}
 @Test public void albumMetadataIsOptionalAndDoesNotUseUploadDate()throws Exception{LauncherinTrack t=LauncherinNativeMusicTest.track(1);assertEquals("",t.album);assertEquals(0,t.year);LauncherinTrack full=t.withAlbum("Álbum real",2020);assertEquals("Álbum real",LauncherinTrack.read(full.json()).album);assertEquals(2020,LauncherinTrack.read(full.json()).year);assertEquals(0,t.withAlbum("Álbum",9999).year);}
 @Test public void artistMatchingRequiresOneIdentityAndKeepsFavoriteOrder(){LauncherinArtistPhotos.Profile a=new LauncherinArtistPhotos.Profile("Skank","https://music.youtube.com/channel/one","https://example.org/a.jpg"),other=new LauncherinArtistPhotos.Profile("Skank cover","x","https://example.org/b.jpg");assertSame(a,LauncherinArtistPhotos.exact("Skank - Topic",Arrays.asList(a,other)));assertNull(LauncherinArtistPhotos.exact("Skank",Arrays.asList(a,new LauncherinArtistPhotos.Profile("Skank","another","https://example.org/c.jpg"))));LauncherinMusicLibrary l=new LauncherinMusicLibrary(c);LauncherinMusicLibrary.Artist first=new LauncherinMusicLibrary.Artist("Skank","youtube",""),second=new LauncherinMusicLibrary.Artist("M83","youtube","");l.saveArtist(first);l.saveArtist(second);l.updateArtistArt(first,a.art);assertEquals("M83",l.artists().get(0).name);assertEquals(a.art,l.artists().get(1).art);}
 @Test public void catalogUrlsRejectForeignHostsAndLocalFiles(){assertTrue(LauncherinMusicCatalog.valid("https://music.youtube.com/playlist?list=OLAK5uy_example"));assertTrue(LauncherinMusicCatalog.valid("https://soundcloud.com/artist/sets/album"));for(String bad:new String[]{"file:///local","https://evil.test/playlist?list=a","https://youtube.com.evil.test/playlist?list=a","https://user@youtube.com/playlist?list=a"})assertFalse(LauncherinMusicCatalog.valid(bad));}
}
